<?php
namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Http\Requests\StoreGoodsReceiptRequest; use App\Models\{GoodsReceipt,PurchaseOrder,Warehouse}; use App\Services\PurchaseManagementService; use Illuminate\Http\RedirectResponse; use Inertia\{Inertia,Response};
class GoodsReceiptController extends Controller { public function __construct(protected PurchaseManagementService $service){} public function index():Response{return Inertia::render('Admin/GoodsReceipts/Index',['receipts'=>GoodsReceipt::with('purchaseOrder.supplier:id,name','warehouse:id,name','receiver:id,name')->latest()->paginate(15)]);} public function create(PurchaseOrder $purchaseOrder):Response{$purchaseOrder->load('supplier','warehouse','items.product');return Inertia::render('Admin/GoodsReceipts/Create',['order'=>$purchaseOrder,'warehouses'=>Warehouse::orderBy('name')->get(['id','name']),'suggestedNumber'=>'GRN-'.now()->format('Ymd-His')]);} public function store(StoreGoodsReceiptRequest $r,PurchaseOrder $purchaseOrder):RedirectResponse{$grn=$this->service->receive($purchaseOrder,$r->validated(),$r->user()->id);return redirect()->route('admin.goods-receipts.show',$grn)->with('success','Goods received and stock updated.');} public function show(GoodsReceipt $goodsReceipt):Response{return Inertia::render('Admin/GoodsReceipts/Show',['receipt'=>$goodsReceipt->load('purchaseOrder.supplier','warehouse','receiver:id,name','items.product')]);}}
